# AMD blog post on MLPerf Training 6.0, held against the result logs of training rounds 5.0, 5.1 and 6.0. Run parse_training_round.py on each clone first. python3 -I check_claims_amd_training_v60.py
import json,hashlib
FILES=['training_v50_times.json','training_v51_times.json','training_v60_times.json']
RAW={f:open(f,'rb').read() for f in FILES}; R={v:json.loads(RAW[f]) for v,f in zip(('50','51','60'),FILES)}
s=str
def t(v,sub,sysn,bench,gpus=8):
    r=[o for o in R[v] if o['submitter']==sub and o['system']==sysn and o['benchmark']==bench and o['gpus']==gpus]; assert len(r)==1,(v,sub,sysn,bench,len(r)); return r[0]['official_style']
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
C=[]
a50=t('50','AMD','MI300X_EPYC_9575F_pytorch','llama2_70b_lora'); a60=t('60','AMD','MI355X_EPYC_9575F_primus','llama2_70b_lora')
C.append(mk('T1','In just over one year, AMD improved performance by 3.5X from its first AMD Instinct MI300X GPU submission using MXFP8 in MLPerf Training 5.0 to the AMD Instinct MI355X GPU submission using MXFP4 in MLPerf Training 6.0.','AMD 8-GPU Llama 2 70B LoRA time to train, round 5.0 MI300X entry against round 6.0 MI355X entry (official-style time: olympic average times the committee scaling factor)','3.5X',f'{a50:.3f} min against {a60:.3f} min = {a50/a60:.2f}x','CONSISTENT' if abs(a50/a60-3.5)<0.1 else 'BELOW','Precision recipes are not in the result files.'))
d=lambda old,new:100*(1-new/old)
l355=d(t('51','AMD','MI355X_EPYC_9575F_pytorch','llama2_70b_lora'),a60); l350=d(t('51','AMD','MI350X_EPYC_9575F_pytorch','llama2_70b_lora'),t('60','AMD','MI350X_EPYC_9575F_primus','llama2_70b_lora'))
b355=d(t('51','AMD','MI355X_EPYC_9575F_pytorch','llama31_8b'),t('60','AMD','MI355X_EPYC_9575F_primus','llama31_8b')); b350=d(t('51','AMD','MI350X_EPYC_9575F_pytorch','llama31_8b'),t('60','AMD','MI350X_EPYC_9575F_primus','llama31_8b'))
C.append(mk('T2','Llama 2-70B fine-tuning: MI355X improved by 19%, while MI350X improved by 16%.','AMD 8-GPU Llama 2 70B LoRA, round 5.1 entries against round 6.0 entries, reduction in time to train','19% and 16%',f'MI355X {l355:.1f}% shorter, MI350X {l350:.1f}% shorter','CONSISTENT' if abs(l355-19)<0.6 and abs(l350-16)<0.6 else 'BELOW','The percentages reproduce as reductions in time to train. As speedups they would be 23% and 19%.'))
C.append(mk('T3','Llama 3.1-8B pre-training: MI355X improved by 13%, while MI350X improved by 11%.','AMD 8-GPU Llama 3.1 8B, round 5.1 entries against round 6.0 entries, reduction in time to train','13% and 11%',f'MI355X {b355:.1f}% shorter, MI350X {b350:.1f}% shorter','CONSISTENT' if abs(b355-13)<0.6 and abs(b350-11)<0.6 else 'BELOW','Reductions in time to train.'))
b200=lambda bench:[o for o in R['60'] if o['gpus']==8 and 'B200' in s(o['accelerator']) and 'GB200' not in s(o['accelerator']) and o['benchmark']==bench]
fl=min(b200('llama2_70b_lora'),key=lambda o:o['official_style']); f8=min(b200('llama31_8b'),key=lambda o:o['official_style'])
g2=100*(1-fl['official_style']/a60 ) if False else 100*(1-(fl['official_style']/a60)); g8=100*(1-(f8['official_style']/t('60','AMD','MI355X_EPYC_9575F_primus','llama31_8b')))
C.append(mk('T4','coming within 5% on Llama 2-70B fine-tuning and within 6% on Llama 3.1-8B pre-training','AMD 8 x MI355X round 6.0 entries against the fastest 8 x B200 SXM entries in round 6.0 (not GB200), throughput as the inverse of time to train','within 5% and within 6%',
 f'Llama 2 70B: fastest B200 entry {fl["submitter"]} {fl["official_style"]:.3f} min, AMD {a60:.3f} min, AMD throughput {100*fl["official_style"]/a60:.1f}% of it. Llama 3.1 8B: fastest B200 entry {f8["submitter"]} {f8["official_style"]:.3f} min, AMD {t("60","AMD","MI355X_EPYC_9575F_primus","llama31_8b"):.3f} min, {100*f8["official_style"]/t("60","AMD","MI355X_EPYC_9575F_primus","llama31_8b"):.1f}%',
 'CONSISTENT' if 100*fl['official_style']/a60>=94.9 and 100*f8['official_style']/t('60','AMD','MI355X_EPYC_9575F_primus','llama31_8b')>=94 else 'BELOW','The statement does not name the B200 entry. This uses the fastest in the file. Against the slower B200 entries AMD is ahead. Precision (MXFP4 and NVFP4) is not in the file.'))
o=[x for x in R['60'] if x['submitter']=='Oracle' and x['benchmark']=='flux1' and 'AMD' in s(x['accelerator'])][0]; am=[x for x in R['60'] if x['submitter']=='AMD' and x['benchmark']=='flux1'][0]
nvmax=max(x['gpus'] for x in R['60'] if x['submitter']=='NVIDIA' and x['benchmark']=='flux1'); nvall=max(x['gpus'] for x in R['60'] if x['submitter']=='NVIDIA')
C.append(mk('T5','AMD submitted FLUX.1 at 64 Instinct MI325X GPUs, while Oracle Cloud Infrastructure, in collaboration with AMD, submitted FLUX.1 at 512 GPUs.','FLUX.1 entries from AMD and Oracle in round 6.0, GPU counts and accelerators','64 MI325X GPUs and 512 GPUs',f'AMD {am["gpus"]} x {s(am["accelerator"])[:24]}, Oracle {o["gpus"]} x {s(o["accelerator"])[:24]}','CONSISTENT' if am['gpus']==64 and o['gpus']==512 else 'BELOW',''))
C.append(mk('T6',"With the 512-GPU OCI result, AMD matched NVIDIA's largest scale with a 512-GPU Training submission.",'largest NVIDIA GPU count in round 6.0, for FLUX.1 and for any benchmark','matched NVIDIA at 512 GPUs',f'NVIDIA largest FLUX.1 entry: {nvmax} GPUs. NVIDIA largest entry in any benchmark: {nvall} GPUs','CONSISTENT' if nvmax==512 else 'BELOW','It matches for FLUX.1. NVIDIA entries in other benchmarks are larger.'))
sub={v:sorted({x['submitter'] for x in R[v] if 'MI3' in s(x['accelerator']) and x['submitter']!='AMD'}) for v in R}
C.append(mk('T7','This round included a record 10 ecosystem partners submitting MLPerf Training results on AMD Instinct GPU-based platforms','submitters other than AMD with an AMD Instinct accelerator in rounds 5.0, 5.1 and 6.0','a record 10 partners',f'Round 5.0: {len(sub["50"])}. Round 5.1: {len(sub["51"])}. Round 6.0: {len(sub["60"])} ({", ".join(sub["60"])})','CONSISTENT' if len(sub['60'])==10 and len(sub['60'])>max(len(sub['50']),len(sub['51'])) else 'BELOW','The list in the post names MiTAC and MiTAC + Akash separately and omits tinycorp. The file has one MiTAC submitter and a tinycorp entry. Rounds before 5.0 are not read.'))
part=[('Oracle','8xMI355X_2xEPYC_9575F'),('Dell','1xXE9785L_8xMI355X'),('Dell','1xXE9785_8xMI355X'),('HPE','HPE-Compute-XD685-MI355X-288GBx8'),('Supermicro','AS-4126GS-NMR-LCC_8xMI355X_OAM'),('MiTAC','8xMI355X_2xEPYC_9755'),('vultr','8xMI355X_2xEPYC_9575F'),('GigaComputing','G893-ZX1-AAX4_pytorch')]
dev=[]
for b,ref in (('llama2_70b_lora',a60),('llama31_8b',t('60','AMD','MI355X_EPYC_9575F_primus','llama31_8b'))):
    for sub_,sysn in part:
        r=[x for x in R['60'] if x['submitter']==sub_ and x['system']==sysn and x['benchmark']==b]
        if r: dev.append((100*abs(r[0]['official_style']/ref-1),sub_,b,r[0]['official_style'],ref))
mx=max(dev)
C.append(mk('T8','Across the partner submissions, results landed within 6% of official AMD submissions across both major LLM training workloads','eight partner 8 x MI355X entries (Oracle, Dell x2, HPE, Supermicro, MiTAC, Vultr, GigaComputing) against the AMD 8 x MI355X entry, time to train, both benchmarks','within 6%',f'Largest difference {mx[0]:.1f}% ({mx[1]}, {mx[2]}, {mx[3]:.3f} min against {mx[4]:.3f} min). Llama 2 70B largest {max(d_ for d_ in dev if d_[2]=="llama2_70b_lora")[0]:.1f}%. Llama 3.1 8B largest {max(d_ for d_ in dev if d_[2]=="llama31_8b")[0]:.1f}%','CONSISTENT' if mx[0]<=6.0 else 'BELOW','Every partner entry is slower than the AMD entry. MI350X partner entries and non-listed submitters are not in this set.'))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=C),open('claims_amd_training_v60.json','w'),indent=1)
for c in C: print(c['id'],c['outcome'],'|',c['stated'],'|',c['delivered'][:230])
